#: The statuses in which an item held its ledger entry under the old partial unique index.
LIVE_ITEM_STATUSES = ("RESERVED", "SUBMITTED", "PAID", "UNDER_REVIEW")


def copy_item_entries_to_lines(apps, schema_editor):
    item_model = apps.get_model("payouts", "PayoutBatchItem")
    line_model = apps.get_model("payouts", "PayoutItemEntry")
    line_model.objects.bulk_create(
        line_model(
            item_id=item.id,
            ledger_entry_id=item.ledger_entry_id,
            amount_paise=item.amount_paise,
            is_live=item.status in LIVE_ITEM_STATUSES,
        )
        for item in item_model.objects.all().iterator()
    )


